@startuml

class Animal {
  + ID
  + name
  + breed
}

class Owner {
  + ID
  + name
  + address
  + phone_number
}

class Breed {
  + name
}

class Physician {
  + ID
  + name
  + address
  + phone_number
}

class Appointment {
  + start_date_time
}

class Condition {
  + common_name
  + scientific_name
}

Appointment "*" -- "1" Physician : responsible physician
Appointment "*" -- "1" Animal : attended
Appointment "*" -- "1" Owner : attended
Animal "0..1" -- "1" Owner : owner
Animal "*" -- "0..1" Breed : breed
Breed "1" -- "*" Condition : common conditions

@enduml

